function M.resolve(language)
    if type(language) ~= "string" then language = tostring(language or "en") end
    language = language:gsub("_", "-"):lower()
    if M.aliases[language] then return M.aliases[language] end
    for _, code in ipairs(M.languages) do
        if code:lower() == language then return code end
    end
    return "en"
end

function M.entry(language)
    return M.data[M.resolve(language)] or M.data.en
end

function M.format(language, key, source, target)
    local text = M.entry(language)[key] or M.data.en[key]
    if source then text = text:gsub("{source}", source) end
    if target then text = text:gsub("{target}", target) end
    return text
end

return M
